@font-face{font-family:HybridSinhala;font-weight:700;src:url(data:font/woff2;base64,<?= base64_encode(file_get_contents(APP_ROOT.'/public/assets/fonts/NotoSansSinhala-Bold.woff2')) ?>) format('woff2');unicode-range:U+0D80-0DFF,U+200C-200D}
