</style><?php if(!$pdf): ?><script defer src="<?= $e(AuthController::url('/assets/js/invoice-documents.js')) ?>"></script><?php endif; ?></head><body>
<?php if(!$pdf): ?><nav class="actions"><a href="<?= $e(AuthController::url($base.'/'.$record['id'])) ?>"><?= $t('Invoice details') ?></a><button type="button" data-print-document><?= $t('Print') ?></button><?php foreach(['58','80']as$w): ?><a href="<?= $e($url('receipt',$locale,$w)) ?>"><?= $e($w) ?>mm</a><?php endforeach; ?><a href="<?= $e($url('a4',$locale,$paper)) ?>">A4</a><a href="<?= $e($url('pdf',$locale,$paper).'&layout='.$layout) ?>"><?= $t('Download PDF') ?></a><a lang="si-LK" href="<?= $e($url($layout==='a4'?'a4':'receipt','si-LK',$paper)) ?>">සිංහල</a><a lang="en" href="<?= $e($url($layout==='a4'?'a4':'receipt','en',$paper)) ?>">English</a></nav><?php endif; ?>
<main class="hybrid-sheet" data-policy="HYBRID_PROMOTION_V1"><header><h1><?= $e($record['company'][$locale==='si-LK'&&!empty($record['company']['name_si'])?'name_si':'name']??'Dharma Chemical') ?></h1><?php foreach(['address','phone','email']as$key):$contact=$record['company'][$locale==='si-LK'&&!empty($record['company'][$key.'_si'])?$key.'_si':$key]??'';if($contact!==''): ?><p><?= $e($contact) ?></p><?php endif;endforeach; ?><h2><?= $t($kind) ?></h2><p><?= $t('Original invoice') ?>: <?= $e($record['invoice_number']) ?></p><p><?= $t('Date') ?>: <?= $e($return['created_at_utc']??$record['business_date']) ?><?= $return?' UTC':'' ?></p><p><?= $t($record['validity']) ?> · LKR</p><?php if($return): ?><p class="reference"><?= $t('Reference') ?>: <?= $e($return['id']) ?></p><?php endif; ?></header>
<section><h3><?= $t('Customer') ?></h3><p><?= $e($record['customer']['shop_name']) ?></p><p><?= $e($record['customer']['address']) ?></p><p><?= $t('Representative') ?>: <?= $e($record['rep_name_snapshot']) ?></p></section>
<?php if(!$return): ?>
<?php foreach($calc['lines']as$line):$item=$items[$line['product_id']]; ?><article><h3><?= $e(I18n::product($item)) ?></h3><small><?= $e($item['sku_snapshot']) ?></small><dl>
<?php $row('Paid quantity',$line['paid_quantity']);$row('Qualified quantity',$line['qualifying_paid_quantity']);$row('Remainder quantity',$line['discount_eligible_quantity']);$row('Actual free quantity',$line['actual_free_quantity']);$row('Unit price',$line['unit_price']);$row('Product discount',$line['product_discount_percent'].'% / '.$line['product_discount_amount']);$row('Replacement discount',($line['replacement_discount_percent']??'0.00').'% / '.$line['replacement_discount_amount']);$row('Invoice discount',$calc['invoice_discount_percent'].'% / '.$line['invoice_discount_amount']);$row('Line payable',$line['payable_amount']); ?>
</dl></article><?php endforeach; ?>
<section class="grand"><dl><?php foreach(['original_paid_subtotal'=>'Original paid subtotal','product_discount_total'=>'Product discount','replacement_discount_total'=>'Replacement discount','invoice_discount_amount'=>'Invoice discount','combined_monetary_discount'=>'Combined monetary discounts','final_payable_total'=>'Final payable']as$key=>$label)$row($label,$calc[$key]); ?></dl></section>
<?php else: ?>
<?php foreach($return['plan']['lines']as$line):$item=$items[$line['product_id']]; ?><article><h3><?= $e(I18n::product($item)) ?></h3><dl><?php $row('Returned paid quantity',$line['receipt']['paid_quantity']);$row('Recovered free quantity',$line['receipt']['free_quantity']);foreach(['gross_amount'=>'Original gross reversed','product_discount_amount'=>'Product discount','replacement_discount_amount'=>'Replacement discount','invoice_discount_amount'=>'Invoice discount','net_credit'=>'Original-net credit']as$key=>$label)$row($label,$line[$key]); ?></dl><p><?= $t('Condition at receipt') ?></p><dl><?php foreach(['paid'=>'Paid','free'=>'Free']as$unit=>$unitLabel)foreach(['SALEABLE'=>'Saleable','QUARANTINE'=>'Quarantine','UNSALEABLE'=>'Unsaleable']as$key=>$label): ?><div class="amount-row"><dt><?= $t($unitLabel) ?> / <?= $t($label) ?></dt><dd><?= $e($line['receipt'][$unit.'_conditions'][$key]) ?></dd></div><?php endforeach; ?></dl><p><?= $t('Reason') ?>: <?= $e($line['receipt']['condition_reason']) ?></p><p><?= $t('Holding location') ?>: <?= $e($line['receipt']['holding_reference']) ?></p></article><?php endforeach; ?>
<section class="grand"><dl><?php $row('Original-net credit',$return['net_credit']);$row('Receivable reduction',$return['debt_reduction']);$row('Refund Due increment',$return['refund_increment']); ?></dl><p><?= $t('Reason') ?>: <?= $e($return['reason']) ?></p><p class="reference"><?= $t('Custody') ?>: <?= $e($return['custody_id']??'-') ?></p></section>
<section class="audit"><h3><?= $t('Manager disposition and audit') ?></h3><?php foreach($return['events']as$event): ?><article><p><?= $t('Version') ?> <?= $e($event['version']) ?> · <?= $t($event['event_type']) ?> · <?= $e($event['created_at_utc']) ?> UTC</p><p><?= $t('Actor') ?>: <?= $e($event['actor']) ?></p><p><?= $t('Reason') ?>: <?= $e($event['reason']) ?></p><?php $data=json_decode($event['event_json'],true,512,JSON_THROW_ON_ERROR)['data'];if(isset($data['quantity'])): ?><dl><?php $row('Original line',$data['line_number']);$row('Quantity',$data['quantity']); ?><div class="amount-row condition-row"><dt><?= $t($data['unit_kind']==='paid'?'Paid':'Free') ?></dt><dd><?= $t(['QUARANTINE'=>'Quarantine','UNSALEABLE'=>'Unsaleable'][$data['from']]) ?> → <?= $t(['SALEABLE'=>'Saleable','QUARANTINE'=>'Quarantine','UNSALEABLE'=>'Unsaleable','DISPOSED'=>'Disposed'][$data['to']]) ?></dd></div></dl><?php endif; ?><p class="reference"><?= $t('Reference') ?>: <?= $e($event['id']) ?> / <?= $e($event['command_id']) ?></p><?php if($event['stock_transaction_id']): ?><p class="reference"><?= $t('Stock transaction') ?>: <?= $e($event['stock_transaction_id']) ?></p><?php endif; ?></article><?php endforeach; ?><p><?= $t('No physical stock release is implied by this document.') ?></p></section>
<?php endif; ?>
<?php if($record['receipts']): ?><section><h3><?= $t('Cash receipt history') ?></h3><?php foreach($record['receipts']as$receipt): ?><article><p class="reference"><?= $t('Reference') ?>: <?= $e($receipt['request_id']) ?> · <?= $e($receipt['created_at_utc']) ?> UTC</p><dl><?php $row('Received',$receipt['received_amount']);$row('Applied',$receipt['applied_amount']);$row('Change',$receipt['change_amount']); ?></dl></article><?php endforeach; ?></section><?php endif; ?><section><h3><?= $t('Current balance as of') ?> <?= $e(gmdate('Y-m-d H:i:s')) ?> UTC</h3><dl><?php foreach(['grand_total'=>'Final payable','paid_amount'=>'Paid / applied','linked_return_credit'=>'Linked credits','outstanding'=>'Outstanding','refund_due'=>'Refund Due']as$key=>$label)$row($label,$key==='linked_return_credit'?$record['hybrid']['financial'][$key]:$record[$key]); ?></dl><p class="warning"><?= $t('Refund Due is a liability. Actual cash refunds are not recorded by this system.') ?></p></section>
<footer><p><?= $t('Original components remain unchanged.') ?></p><p class="reference"><?= $e($record['hybrid']['policy_version']) ?> · <?= $e($record['hybrid']['seal_digest']) ?></p><?php $footer=$record['company'][$locale==='si-LK'&&!empty($record['company']['footer_si'])?'footer_si':'footer']??'';if($footer!==''): ?><p><?= $e($footer) ?></p><?php endif; ?></footer></main></body></html>
